"""Bloques de participa.html. Se tomaron de index.html (pestaña «Portal
digital» y cajón «Ayúdanos a fiscalizar») el 09-10-2026, cuando el autor
pidió que el contenido viviera dentro de las pestañas de Participa. Los
pinta y los hace funcionar assets/auditor/js/participa.js."""

CANALES = '<div class="fj-bloque" id="bloqueCanales">\n        <div class="fj-bloque-head">\n          <span class="fj-kicker">Función 2</span>\n          <h3>Las seis puertas donde un señalamiento se vuelve expediente</h3>\n        </div>\n        <p class="fj-bloque-sub">\n          Esta es la parte que sí tiene efecto jurídico, y la que casi nadie usa porque no se sabe cuál toca. Cada ficha responde lo mismo: qué investiga ese órgano, si admite denuncia anónima, qué debe tener a la mano antes de empezar y qué produce su denuncia una vez presentada. Una de las seis no es un canal de denuncia sino la herramienta para conseguir la prueba: léala primero si todavía no tiene documentos.\n        </p>\n        <div id="canalesOficialesContainer" class="canales-denuncia-list"></div>\n\n        <div class="dec-wrap" id="decalogoWrap">\n          <div class="dec-head">\n            <span class="dec-kicker">Decálogo del ciudadano auditor</span>\n            <h4>Diez reglas que hacen la diferencia entre una queja y una denuncia</h4>\n            <p>No son consignas: cada una tiene detrás una norma concreta. Están ordenadas de lo general a lo práctico, y la última es la que más se olvida.</p>\n          </div>\n          <div id="decalogoContainer" class="dec-grid"></div>\n        </div>\n      </div>'

PORTAL = '<div class="portal-digital-block" id="bloquePortal">\n        \n        <!-- Banner Hero del Portal & Garantía de Privacidad -->\n        <div class="portal-banner-hero">\n          <div class="portal-title-group">\n            <span class="hero-tag" style="background:rgba(201,168,76,0.15); color:var(--gold-bright); border:1px solid var(--border-gold); padding:3px 10px; border-radius:4px; font-size:11px; font-family:var(--font-mono); text-transform:uppercase; letter-spacing:1px; display:inline-block; margin-bottom:6px;">\n              🌐 Red Social Cívica &amp; Ágora Libre\n            </span>\n            <h3>\n              <span>💬</span> Portal Público Digital · ¿Quieres Dialogar o Replicar?\n            </h3>\n            <p>\n              Un espacio para ordenar posturas, plantear tesis críticas y sostenerlas con fuentes oficiales sobre cualquier contenido de la plataforma. <strong>Por ahora, lo que escribas se guarda sólo en este navegador</strong>: nadie más lo ve todavía. No se piden correos, teléfonos ni nombres reales; basta un <strong>nick o pseudónimo</strong>.\n            </p>\n          </div>\n\n          <div class="portal-privacy-badges">\n            <span class="privacy-pill green" title="El formulario no pide correo, teléfono ni nombre real">\n              <span>🔒</span> Sin correo ni teléfono\n            </span>\n            <span class="privacy-pill gold" title="Elige tu alias libremente">\n              <span>🎭</span> Acceso con Nick / Pseudónimo\n            </span>\n            <span class="privacy-pill cyan" title="Libre debate de argumentos y fuentes">\n              <span>⚖️</span> Debate de Ideas &amp; Fuentes\n            </span>\n          </div>\n        </div>\n\n        <!-- Formulario Creador de Nuevo Debate / Argumento -->\n        <div class="portal-creator-card">\n          <h4>\n            <span>✍️</span> Iniciar Nuevo Diálogo o Postura Ciudadana\n          </h4>\n\n          <form id="portalNuevoDebateForm" onsubmit="window.AuditEngine.submitNuevoDebate(event)">\n            <div class="creator-form-grid">\n              \n              <!-- Campo de Nick / Pseudónimo -->\n              <div class="com-form-row">\n                <label for="portalNick">\n                  <span>Tu Nick o Pseudónimo Cívico</span>\n                  <span style="color:var(--gold-bright); cursor:pointer;" onclick="window.AuditEngine.generarRandomNick()" title="Generar un Nick aleatorio">🎲 Aleatorio</span>\n                </label>\n                <input type="text" id="portalNick" maxlength="35" placeholder="Ej. @AuditorRegio, @CiudadanoDelSur" required style="background:var(--bg-card); border:1px solid var(--border-subtle); color:#fff; padding:10px 14px; border-radius:6px; font-family:var(--font-mono); font-size:12.5px;">\n              </div>\n\n              <!-- Selector de Tema de la Plataforma -->\n              <div class="com-form-row">\n                <label for="portalTemaSel">Tema o Pestaña Relacionada</label>\n                <select id="portalTemaSel" style="background:var(--bg-card); border:1px solid var(--border-subtle); color:#fff; padding:10px 14px; border-radius:6px; font-size:12.5px;">\n                  <option value="presupuesto">📊 Presupuesto &amp; PEF (Pestaña 1)</option>\n                  <option value="megaobras">🏗️ Megaobras &amp; Costos (Pestaña 2)</option>\n                  <option value="legislativo">🏛️ Poder Legislativo (Pestaña 3)</option>\n                  <option value="judicial">⚖️ Suprema Corte SCJN (Pestaña 4)</option>\n                  <option value="politicos">👥 Personajes &amp; Sexenios (Pestaña 5)</option>\n                  <option value="deuda">📈 Deuda, CETES &amp; Banxico (Pestaña 2)</option>\n                  <option value="general">🌐 Debate Cívico General</option>\n                </select>\n              </div>\n\n              <!-- Selector de Postura / Enfoque -->\n              <div class="com-form-row">\n                <label>Tu Postura o Enfoque</label>\n                <div class="stance-selector-group" id="portalStanceGroup">\n                  <button type="button" class="stance-btn-radio active" data-stance="matiz" onclick="window.AuditEngine.selectStance(\'matiz\')">\n                    <span>🟡</span> Matiz\n                  </button>\n                  <button type="button" class="stance-btn-radio" data-stance="a_favor" onclick="window.AuditEngine.selectStance(\'a_favor\')">\n                    <span>🟢</span> A Favor\n                  </button>\n                  <button type="button" class="stance-btn-radio" data-stance="en_contra" onclick="window.AuditEngine.selectStance(\'en_contra\')">\n                    <span>🔴</span> En Contra\n                  </button>\n                  <button type="button" class="stance-btn-radio" data-stance="aporte" onclick="window.AuditEngine.selectStance(\'aporte\')">\n                    <span>📄</span> Aporte\n                  </button>\n                </div>\n                <input type="hidden" id="portalStanceVal" value="matiz">\n              </div>\n\n            </div>\n\n            <!-- Título / Tesis del Argumento -->\n            <div class="com-form-row">\n              <label for="portalTesis">\n                <span>Tesis Central o Título del Argumento</span>\n                <span style="color:var(--text-dim);">Conciso y claro</span>\n              </label>\n              <input type="text" id="portalTesis" maxlength="160" placeholder="Ej. El subsidio operativo del Tren Maya debe compararse con la derrama hotelera regional..." required style="background:var(--bg-card); border:1px solid var(--border-subtle); color:#fff; padding:10px 14px; border-radius:6px; font-family:var(--font-serif); font-size:14px;">\n            </div>\n\n            <!-- Contenido Argumentativo Completo -->\n            <div class="com-form-row">\n              <label for="portalContenido">\n                <span>Desarrollo del Argumento, Razonamiento o Postura Cívica</span>\n                <span id="portalCharCount" style="color:var(--text-dim);">0 / 1200</span>\n              </label>\n              <textarea id="portalContenido" maxlength="1200" placeholder="Expón tus razones, datos o contrastes. Mantén un tono de debate cívico constructivo y fundamentado..." required style="background:var(--bg-card); border:1px solid var(--border-subtle); color:#fff; padding:12px 14px; border-radius:6px; font-size:13px; line-height:1.6; min-height:110px;"></textarea>\n            </div>\n\n            <!-- Fuente o Enlace de Verificación (Opcional) -->\n            <div class="com-form-row">\n              <label for="portalFuente">\n                <span>Fuente Documental o Enlace Oficial (Opcional pero Recomendado)</span>\n                <span style="color:var(--cyan);">Cita de ley, nota oficial, ASF, DOF, etc.</span>\n              </label>\n              <input type="text" id="portalFuente" maxlength="180" placeholder="Ej. Cuenta Pública ASF 2024 / Ley de Ingresos LIF 2026 Art. 1" style="background:var(--bg-card); border:1px solid var(--border-subtle); color:#fff; padding:8px 14px; border-radius:6px; font-family:var(--font-mono); font-size:12px;">\n            </div>\n\n            <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px; margin-top:16px;">\n              <span style="font-size:11.5px; color:var(--text-dim); font-family:var(--font-mono);">\n                🤝 Reglas: Respeto estricto, debate de ideas, cero discursos de odio.\n              </span>\n              <button type="submit" class="calc-btn" style="padding:10px 24px; font-size:12.5px; display:inline-flex; align-items:center; gap:8px;">\n                <span>💾</span> Guardar argumento en este navegador\n              </button>\n            </div>\n            <div id="portalFormStatusMsg" style="margin-top:8px; font-family:var(--font-mono); font-size:11.5px;"></div>\n          </form>\n        </div>\n\n        <!-- Barra de Filtros Temáticos del Foro -->\n        <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:14px; margin-bottom:20px; border-bottom:1px solid var(--border-subtle); padding-bottom:14px;">\n          <div>\n            <h4 style="font-family:var(--font-serif); font-size:18px; color:var(--gold-bright); margin:0;">\n              🗣️ Diálogos, Réplicas &amp; Hilos en Curso\n            </h4>\n            <span style="font-size:11.5px; color:var(--text-dim); font-family:var(--font-mono);">\n              Haz clic en «Replicar» para participar en cualquier discusión ciudadana\n            </span>\n          </div>\n\n          <div class="presets-bar" id="portalFilterBar" style="margin-bottom:0;">\n            <button class="chip on active" data-forum-filter="todos" onclick="window.AuditEngine.filterPortalDebates(\'todos\')">🌐 Todos</button>\n            <button class="chip" data-forum-filter="presupuesto" onclick="window.AuditEngine.filterPortalDebates(\'presupuesto\')">📊 Presupuesto</button>\n            <button class="chip" data-forum-filter="megaobras" onclick="window.AuditEngine.filterPortalDebates(\'megaobras\')">🏗️ Megaobras</button>\n            <button class="chip" data-forum-filter="judicial" onclick="window.AuditEngine.filterPortalDebates(\'judicial\')">⚖️ SCJN</button>\n            <button class="chip" data-forum-filter="politicos" onclick="window.AuditEngine.filterPortalDebates(\'politicos\')">👥 Personajes</button>\n            <button class="chip" data-forum-filter="deuda" onclick="window.AuditEngine.filterPortalDebates(\'deuda\')">📈 Deuda &amp; Banxico</button>\n          </div>\n        </div>\n\n        <!-- Contenedor Dinámico de Tarjetas de Debates & Réplicas -->\n        <div id="portalDebatesListContainer" class="portal-debates-container"></div>\n\n      </div>'

APORTAR = '\n      <p class="fj-bloque-sub" style="margin-top:0;">\n        No necesitas ser contador ni abogado. Necesitas haber visto algo y poder decir <em>qué</em>, <em>dónde</em> y <em>cuándo</em>. Lo que registres aquí queda guardado en tu navegador y podrás copiarlo con un botón para presentarlo, ya redactado, en cualquiera de los canales oficiales ante la ASF, la Secretaría Anticorrupción y Buen Gobierno o su contraloría local.\n        <strong style="display:block; margin-top:6px; color:var(--gold-bright);">No compartas datos bancarios, documentos de identidad ni información de terceros que pueda ponerlos en riesgo.</strong>\n      </p>\n\n      <div class="com-util">\n        <div class="com-util-tit">Qué vuelve útil un reporte</div>\n        <ul class="com-util-lista">\n          <li><strong>Qué.</strong> La obra, el contrato, el programa o el trámite, con su nombre tal como aparece en la placa o en el recibo.</li>\n          <li><strong>Dónde.</strong> Municipio, colonia y referencia física. Una dirección vale más que un adjetivo.</li>\n          <li><strong>Cuándo.</strong> La fecha o el periodo. Los fondos se fiscalizan por ejercicio anual.</li>\n          <li><strong>Con qué dinero.</strong> Si lo sabes: Ramo 33, FISMDF, FORTAMUN, recurso estatal o propio del municipio.</li>\n          <li><strong>Con qué prueba.</strong> Una foto con fecha, un número de contrato, una factura, un acta de entrega.</li>\n        </ul>\n      </div>\n\n      <div class="com-card-panel">\n        <form id="comunidadForm">\n          <div class="com-form-row">\n            <label for="comNombre">Nombre o Pseudónimo (Opcional)</label>\n            <input type="text" id="comNombre" maxlength="60" placeholder="Ej. Ciudadano de Guadalajara">\n          </div>\n\n          <div style="display:grid; grid-template-columns: 1fr 1fr; gap:14px;">\n            <div class="com-form-row">\n              <label for="comTipo">Tipo de Participación</label>\n              <select id="comTipo">\n                <option value="Obra pública">Una obra que no cuadra</option>\n                <option value="Contrato o compra">Un contrato o una compra sospechosa</option>\n                <option value="Programa social">Uso electoral de un programa social</option>\n                <option value="Trámite o cobro">Un cobro o trámite indebido</option>\n                <option value="Corrección de dato">Corrección a un dato de esta plataforma</option>\n                <option value="Duda presupuestal">Duda sobre gasto o presupuesto</option>\n                <option value="Sugerencia">Sugerencia para la plataforma</option>\n              </select>\n            </div>\n            <div class="com-form-row">\n              <label for="comEstadoSel">Entidad Relacionada</label>\n              <select id="comEstadoSel">\n                <option value="Nacional">Nacional / Federal</option>\n              </select>\n            </div>\n          </div>\n\n          <div class="com-form-row">\n            <label for="comMensaje">\n              <span>Tu mensaje u observación cívica</span>\n              <span id="comCharCount" style="color:var(--text-dim);">0 / 1000</span>\n            </label>\n            <textarea id="comMensaje" maxlength="1000" placeholder="Describe la obra, el fondo (Ramo 33, FORTAMUN) o el aspecto presupuestario que deseas señalar..." required></textarea>\n          </div>\n\n          <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-top:14px;">\n            <button type="submit" class="calc-btn" style="padding:10px 22px;">💾 Guardar en este navegador</button>\n            <span id="comStatusMsg" style="font-family:var(--font-mono); font-size:11px;"></span>\n          </div>\n        </form>\n\n        <div class="com-obs-wrap">\n          <h4 class="com-obs-h4">Observaciones que has registrado en este navegador</h4>\n          <div id="comentariosListContainer"></div>\n        </div>\n      </div>'
